insert into public.metrics (key, label, value, detail, sort_order) values
 ('clinic',      'คลินิกอาคารหน้า รพ.', 'เปิด ม.ค. 70', 'แพทย์ + กายภาพบำบัด · 8 คน · ค่าใช้จ่าย 302,000 บาท/เดือน · ย้ายเข้า รพ. ต.ค. 70', 1),
 ('hospital',    'โรงพยาบาล', '50 เตียง', 'รพ.เฉพาะทางระบบประสาท สมอง และไขสันหลัง เชียงใหม่ มาสเตอร์พีซ · ยื่นคำขอแล้ว 28 ต.ค. 69 · เปิด IPD ต.ค. 70 (สมมติ)', 2),
 ('investment',  'เงินลงทุน', '161.8 ล้านบาท', 'ก่อสร้าง 132.3 · ตกแต่ง ~12.5 · เครื่องมือแพทย์ ~17 · กู้ 66% ≈ 106.8 ล้านบาท', 3),
 ('headcount',   'กำลังคน รพ. + Villa ตอนเต็ม', '118 คน', 'OPD 31 · IPD 68 · Villa 19', 4),
 ('cost',        'ค่าใช้จ่ายตอนเต็ม', '4.53 ล้านบาท/เดือน', '3.63 ล้าน + ค่าผ่อนธนาคาร ~0.90 ล้าน', 5),
 ('bed_revenue', 'รายได้ค่าเตียงสูงสุด (เต็ม 100%)', '3.86–4.22 ล้านบาท/เดือน', 'ไม่พอค่าใช้จ่าย ต้องมีรายได้ OPD + แพ็กเกจเสริม ~1.04 ล้านบาท/เดือน', 6),
 ('cash_24m',    'เงินสดสะสม 24 เดือน (ไม่มีรายได้ OPD)', '−29.8 ล้านบาท', 'แผนเดิม (OPD รพ. มี.ค.) −34.6 ล้านบาท', 7),
 ('leads',       'ผู้สนใจที่ต้องหา', '96 ราย (2570)', '232 รายในปี 2571', 8),
 ('tasks',       'งานหลักทั้งปี', '16 + 4 รายการ', 'งานหลัก 16 รายการ + งานเพิ่ม 4 รายการ', 9),
 ('org',         'โครงสร้างองค์กร', '8 แผนก', 'C-level เหลือ CEO คนเดียว · JD 17 ตำแหน่ง', 10);
insert into public.tasks (sort_order, quarter, title, owner, outcome, due_text, due_date, status, is_extra) values
 (1,  'Q1', 'ยุทธศาสตร์ปี 2570 + สื่อสารให้พนักงานรับทราบ', 'CEO + แผนกบุคคลและธุรการ', 'กรรมการอนุมัติ และพนักงานทุกแผนกรับทราบ', null, null, 'ยังไม่เริ่ม', false),
 (2,  'Q1', 'เปิดคลินิกแพทย์ + กายภาพที่อาคารสำนักงานหน้า รพ. (ยื่นภายใน 30 พ.ย. 69 · เปิด ม.ค. 70)', 'แผนกพยาบาล', 'ได้ใบอนุญาตและเปิดให้บริการ', null, null, 'ยังไม่เริ่ม', false),
 (3,  'Q1', 'วางรูปแบบการจัดการใหม่', 'แผนกพยาบาล', 'รูปแบบการจัดการใหม่ประกาศใช้ทุกสาขา', null, null, 'ยังไม่เริ่ม', false),
 (4,  'Q1', 'เปลี่ยนโครงสร้างบริหาร + จำแนกแผนก + แต่งตั้งหัวหน้าแผนก', 'CEO + HR', 'ผังองค์กรและ JD ประกาศใช้', null, null, 'ยังไม่เริ่ม', false),
 (5,  'Q1', 'กำหนด KPI รายแผนก', 'ทุกสาย (HR ประสาน)', 'KPI และค่าเป้าครบทุกแผนก', null, null, 'ยังไม่เริ่ม', false),
 (6,  'Q2', 'ประเมิน KPI รอบแรก', 'HR', 'รายงานผล KPI ครึ่งปีแรก', null, null, 'ยังไม่เริ่ม', false),
 (7,  'Q2', 'ประเมิน Performance รายบุคคล', 'HR + หัวหน้าแผนก', 'ผลประเมินรายคน + แผนพัฒนา', null, null, 'ยังไม่เริ่ม', false),
 (8,  'Q2', 'ทบทวนแผนกลางปี (เพิ่ม)', 'CEO', 'ปรับแผนครึ่งปีหลังจากผล KPI', null, null, 'ยังไม่เริ่ม', false),
 (9,  'Q3', 'วางโครงสร้าง รพ.', 'แผนกบุคคลและธุรการ + แผนกพยาบาล + แผนกบัญชีและการเงิน', 'ผังองค์กร อัตรากำลัง งบดำเนินงาน รพ.', null, null, 'ยังไม่เริ่ม', false),
 (10, 'Q3', 'วางรากฐาน Tranquila International (ทำตั้งแต่ Q1 ทั้งสองทางเลือก)', 'แผนกการตลาด', 'กลุ่มเป้าหมาย ช่องทาง งบ สื่อภาษาอังกฤษ', null, null, 'ยังไม่เริ่ม', false),
 (11, 'Q3–Q4', 'ยื่นขออนุญาต Villa', 'แผนกบุคคลและธุรการ + แผนกพยาบาล', 'ได้ใบอนุญาตก่อนเริ่ม operate', null, null, 'ยังไม่เริ่ม', false),
 (12, 'Q4', 'เริ่มการตลาดต่างประเทศ (ทางเลือก B: ทดลองขาย Q4 ขายเต็มปี 2571)', 'แผนกการตลาด', 'ผู้พักต่างชาติทดลองชุดแรก 1–3 คน (ทาง A)', null, null, 'ยังไม่เริ่ม', false),
 (13, 'Q4', 'เริ่ม Operate Villa', 'แผนกพยาบาล', 'เปิดรับผู้พัก', null, null, 'ยังไม่เริ่ม', false),
 (14, 'Q4', 'สรุปผลทั้งปี + แผนปี 2571 (เพิ่ม)', 'CEO', 'รายงานผลปีและแผนปีถัดไป', null, null, 'ยังไม่เริ่ม', false),
 (15, 'ทั้งปี', 'ระบบแฟรนไชส์กับ Franbiz (ต่อเนื่อง)', 'แผนกบุคคลและธุรการ', 'คู่มือและระบบแฟรนไชส์พร้อมขาย', 'ตามสัญญา', null, 'กำลังทำ', false),
 (16, 'ทั้งปี', 'ติดตามก่อสร้าง รพ. กับ DG และธนาคาร (ต่อเนื่อง)', 'แผนกบัญชีและการเงิน', 'รายงานความคืบหน้ารายเดือน', 'ทุกเดือน', null, 'กำลังทำ', false),
 (17, 'ก่อนเริ่มปี', 'เก็บตัวเลขจริง 6 รายการ (ดูสรุปสำหรับ CEO)', 'แผนกบัญชีและการเงิน', 'ใส่ในไฟล์แผนการเงิน ตัวเลขเงินที่ต้องเตรียมเป็นตัวจริง', '23 พ.ย. 69', '2026-11-23', 'ยังไม่เริ่ม', true),
 (18, 'Q1', 'ติดตามคำขอ ส.พ. ที่ยื่นแล้ว 28 ต.ค. 69 (แก้ 11 จุด) · ถาม สสจ. เรื่อง Villa', 'แผนกบุคคลและธุรการ + แผนกพยาบาล', 'รู้ประเภทใบอนุญาต เอกสาร และระยะเวลา', '31 ม.ค. 70', '2027-01-31', 'ยังไม่เริ่ม', true),
 (19, 'Q2', 'เริ่มสรรหาบุคลากร รพ. (RN PN NA PTA แพทย์ เภสัชกร)', 'HR', 'มีรายชื่อผู้สมัครสำรองก่อนเปิด IPD', '30 มิ.ย. 70', '2027-06-30', 'ยังไม่เริ่ม', true),
 (20, 'Q2', '(ทางเลือก B) ขยาย OPD จาก 1 เป็น 2 ห้องตรวจพร้อมเปิด IPD', 'แผนกพยาบาล', 'แผนขยาย OPD และคนเพิ่ม', '30 ก.ย. 70', '2027-09-30', 'ยังไม่เริ่ม', true);
insert into public.projects (sort_order, name, description, started, owner, kpi_2570, decision, status) values
 (1, 'CMCC Home Care', 'ส่งผู้ดูแลผู้สูงอายุตามบ้าน บันทึกผ่านแอปเยี่ยมบ้าน และส่งรายงานเข้า LINE ครอบครัว', 'ส.ค. 69', 'พี่แหม่ม', 'ปัจจุบันไม่ถึง 10 ราย · ร่างเป้า: 15 รายภายใน มิ.ย. 70 และ 25 รายภายใน ธ.ค. 70 · รายได้/เดือน …… · ต่อสัญญา ……%', 'เป้าเคสและจำนวนผู้ดูแลที่ต้องมี', 'กำลังทำ'),
 (2, 'CMNH Home Rehab', 'ส่ง PT · PTA · OT ตามบ้าน แพ็กเกจ + ค่าเดินทางโซน A/B/C (TMS/PMS ทำที่ศูนย์)', 'ม.ค. 69', 'มิน', 'session/เดือน …… · รายได้/เดือน …… · ซื้อแพ็กเกจต่อ ……%', 'เชื่อมกับคลินิกหน้า รพ. (นายโยธินและเครื่องมือใช้ร่วมกัน)', 'กำลังทำ'),
 (3, 'Single Procedure by Neuro', 'หัตถการตามบ้านโดยคลินิกหมอต้น (ใส่ NG เปลี่ยน Foley ฯลฯ) เฉพาะผู้ป่วยที่เคยตรวจที่คลินิก', 'ส.ค. 69', 'จุ้บแจง', 'หัตถการ/เดือน …… · รายได้/เดือน …… · เวลาตอบรับเคส …… ชม.', 'ทำภายใต้ใบอนุญาตคลินิกหมอต้น แต่รับเงินในนาม CMNH · ต้องมีสัญญาระหว่างคลินิกกับบริษัทและใบเสร็จที่สอดคล้องกัน ให้ทนายตรวจ · เมื่อคลินิกบริษัทหน้า รพ. เปิด พิจารณาย้ายมาใช้ใบอนุญาตบริษัท', 'กำลังทำ'),
 (4, 'CM Derma Plus', 'สกินแคร์ผู้สูงอายุ: Shower Gel, Body Lotion, Coconut Soft Balm', 'ต้นปี 69', 'โมบาย', 'ยอดขาย/เดือน …… · หน่วยที่ขาย …… · สต็อกไม่เกิน …… เดือน', 'ช่องทางขายหลักปี 2570 (สาขา · ออนไลน์ · ตัวแทน)', 'กำลังทำ'),
 (5, 'แพลตฟอร์มระบบหลังบ้าน ADMIN', 'ขายแพ็กเกจ/ใบเสนอราคา · Session Tracker · แอปเยี่ยมบ้าน · ผังเตียงว่าง · ADL · หลังบ้านเช่าออกซิเจน', 'ก.ย. 69', 'มิน', 'งานที่บันทึกผ่านระบบ ……% · ปิดบัญชีรายเดือนภายใน …… วัน', 'ขายระบบแบบ white-label ให้ธุรกิจอื่นหรือไม่ เมื่อไร · เพิ่มระบบคลินิก/OPD', 'กำลังทำ'),
 (6, 'CMCC Health Product', 'ให้เช่า-ขายอุปกรณ์ดูแลผู้ป่วยมือสอง เน้นเครื่องผลิตออกซิเจน มัดจำ 3,000–5,000 บาท', 'ก.ย. 69', 'พี่แหม่ม', 'ปัจจุบันให้เช่ารวมไม่ถึง 10 ราย · ร่างเป้า: เช่าอยู่พร้อมกัน 10 เครื่องภายใน มิ.ย. 70 และ 20 เครื่องภายใน ธ.ค. 70 · รายได้/เดือน ……', 'มัดจำคงที่ต่อรุ่นหรือต่อเคส · จำนวนเครื่องที่จะซื้อเพิ่ม', 'กำลังทำ');
insert into public.kpis (sort_order, department, name, target, frequency) values
 (1,  'CEO', 'งานในตารางงานเสร็จตามกำหนด', '≥ 90%', 'รายไตรมาส'),
 (2,  'แผนกพยาบาล', 'อัตราเข้าพัก สาขา 1–4 / TQL', '≥ 85% / ≥ 80%', 'รายเดือน'),
 (3,  'แผนกพยาบาล', 'อัตราเข้าพัก IPD / Villa', 'ตามแผน: IPD ต.ค. 15% · พ.ย. 25% · ธ.ค. 35% · Villa พ.ย. 15% · ธ.ค. 25%', 'รายเดือน'),
 (4,  'แผนกพยาบาล', 'คลินิกหน้า รพ. → OPD รพ.: ผู้ป่วยต่อเดือน · รายได้คลินิก', 'ม.ค. 40 → ก.ย. 200 → ต.ค. 300 → ธ.ค. 400 ราย (สมมติ) · รายได้ ≥ 302,000 บาท/เดือน', 'รายเดือน (เริ่ม ม.ค.)'),
 (5,  'แผนกพยาบาล', 'พลัดตกใหม่ / แผลกดทับใหม่', '≤ 1.0 ครั้งต่อ 1,000 วันนอน (แต่ละตัว)', 'รายเดือน'),
 (6,  'แผนกพยาบาล + แผนกบุคคลและธุรการ', 'อัตราลาออกพนักงาน', '≤ 2% ต่อเดือน', 'รายเดือน'),
 (7,  'แผนกพยาบาล', 'Day Care และ Home Care: ผู้รับบริการ', '+20% จากค่าฐาน ม.ค. ภายใน ธ.ค.', 'รายเดือน'),
 (8,  'แผนกบัญชีและการเงิน', 'รายได้รวมบริษัท', 'ธุรกิจเดิม +10% จากปี 2569 + รายได้ รพ./Villa ตามแผน', 'รายเดือน'),
 (9,  'แผนกบัญชีและการเงิน', 'ค่าใช้จ่ายโครงการ รพ. + Villa / เงินสดสะสม', 'ไม่เกินแผน / ไม่ต่ำกว่าแผนรายเดือน', 'รายเดือน'),
 (10, 'แผนกบัญชีและการเงิน', 'ปิดงบ / หนี้ค้างเกิน 30 วัน', 'ภายในวันที่ 10 / ≤ 5% ของรายได้', 'รายเดือน'),
 (11, 'แผนกบัญชีและการเงิน', 'งบก่อสร้าง รพ. ใช้จริงเทียบแผน', '≤ 100% (เกิน 5% ต้องขออนุมัติ)', 'รายเดือน'),
 (12, 'แผนกการตลาด', 'lead รพ. + Villa / อัตราปิดการขาย', 'ก.ค. 5 · ส.ค. 10 · ก.ย. 20 · ต.ค.–ธ.ค. 32 ต่อเดือน / ≥ 25%', 'รายเดือน'),
 (13, 'แผนกการตลาด', 'ความพึงพอใจญาติ / เรื่องร้องเรียน', '≥ 4.5 จาก 5 / ≤ 2 เรื่องต่อเดือน', 'รายไตรมาส / รายเดือน'),
 (14, 'แผนกการตลาด', 'ตปท.: ผู้แนะนำ (multipliers) ที่ติดต่อได้ สะสม', 'มี.ค. 3 · มิ.ย. 10 · ก.ย. 20 · ธ.ค. 30', 'รายไตรมาส'),
 (15, 'แผนกการตลาด', 'ตปท.: lead ต่างชาติ', 'ทาง A: 25 ราย (เริ่ม ก.ค.) · ทาง B: 2–3 ราย/เดือน ใน Q4', 'รายเดือน'),
 (16, 'แผนกการตลาด', 'ตปท.: ผู้พักต่างชาติรับใหม่', 'ทาง A: 3 คนภายใน ธ.ค. · ทาง B: เริ่มปี 2571', 'รายเดือน'),
 (17, 'แผนกพยาบาล + แผนกบุคคลและธุรการ', 'ตปท.: พนักงาน TQL ผ่านอบรมภาษาอังกฤษพื้นฐาน', 'มิ.ย. 30% · ก.ย. 50% · ธ.ค. 70%', 'รายไตรมาส');
insert into public.decisions (sort_order, topic, detail, deadline) values
 (1, 'อนุมัติโครงสร้าง CEO + 8 แผนก', 'ตัด Vice CEO, COO, CFO, CMO · การควบ 4 ตำแหน่ง และสายบังคับบัญชา · มอบอำนาจอนุมัติให้หัวหน้าแผนกเป็นลายลักษณ์อักษร', 'ก่อนสิ้น Q1'),
 (2, 'อนุมัติเปิดคลินิกแพทย์ + กายภาพที่อาคารสำนักงานหน้า รพ.', 'ยื่นใบอนุญาตภายใน 30 พ.ย. 69 เปิด ม.ค. 70 และตั้งเป้ารายได้คลินิกไม่ต่ำกว่า 302,000 บาท/เดือน', '30 พ.ย. 69'),
 (3, 'ให้ตัวเลขเงินลงทุน เงินกู้ ประมาณการรายได้ OPD และตัวเลขธุรกิจเดิมปี 2569', 'เพื่อปิดตัวเลขจุดคุ้มทุนจริง', '23 พ.ย. 69'),
 (4, 'ยืนยันเดือนเปิด IPD ราคา Villa T.Tube และประเภทใบอนุญาต Villa', 'แผนสมมติเปิด IPD ต.ค. 70', null),
 (5, 'ตั้งค่าเป้า KPI ทุกสาย + เป้ารายได้ OPD + แพ็กเกจเสริม', 'เป้า OPD + แพ็กเกจเสริมของ รพ. ไม่ต่ำกว่าราว 1 ล้านบาท/เดือนเมื่อเปิดเต็ม', 'ม.ค. 70'),
 (6, 'เลือกเวลาเริ่มขายตลาดต่างประเทศ', 'A: เริ่มขายในสวิส ก.ค. 70 · B: ทดลองขาย Q4 ขายเต็มปี 2571', null);
